import sys,random,copy,json,subprocess
from collections import OrderedDict
sys.path.insert(0,'/workspace/submission')
from crosscheck import CrossCheck
from crosscheck.common_utils import NetworkTopology
from crosscheck.dtp import RepairCertificate
from test_model import brute

def prediction(top, demands, paths):
    result={flow:0 for flow in top.flows if paths is not None or -1 in flow}
    for (a,b),d in zip(top.demand_pairs,demands):
        result[-1,a]+=d;result[b,-1]+=d
        if paths is not None:
            for entry in paths[top.names[a]][top.names[b]]:
                for s,t in zip(entry['path'],entry['path'][1:]):
                    result[top.ids[s],top.ids[t]]+=d*entry['weight']
    for a,b in result:
        if a!=-1 and b!=-1: result[a,b]//=1000
    return tuple(result.get(flow) for flow in top.flows)

def validate(top,c,pred,sett,id):
    rows=[]
    for f,p in enumerate(pred):
        if p is None: continue
        for key in top.flow_keys[f]:
            if c.supports[f]*sett['cutoff'][1] < sett['cutoff'][0]*sett['trials']: continue
            X=c.values[f]*1000000;Y=p*(1000000-sett['bias'])
            okay=1000000*abs(X-Y)<=sett['tau']*max(X,Y)
            rows.append((key,okay))
    N=len(rows);K=sum(v for k,v in rows)
    return {'op':'validate','id':id,'checked':N,'passed':K,'consistent':(K*sett['gamma'][1]>=N*sett['gamma'][0]) if N else None, 'failed':sorted(k for k,v in rows if not v)}

def ref(stream):
    top=NetworkTopology(stream['topology']);sett=stream['settings'];ms=[None]*len(top.counter_keys);ds=[0]*len(top.demand_pairs);paths=None;snaps={};cache=OrderedDict();out=[]
    for e in stream['events']:
        if e['op']=='patch':
            # generator adds a marker to convey intended validity, actual candidate input doesn't contain marker
            valid=e.get('valid',True)
            out.append({'op':'patch','accepted':valid})
            if valid:
                for a,b,v in e['demands']:ds[top.demand_index[a,b]]=v
                for k,c in e['counters'].items():ms[top.counter_index[k]]=c['perturbed'] if c is not None else None
        elif e['op']=='routes':
            paths=copy.deepcopy(e['paths']);out.append({'op':'routes','accepted':True})
        elif e['op']=='repair':
            # equivalent object order via canonical JSON; bundle sort too.
            ps=copy.deepcopy(paths)
            if ps is not None:
                for dests in ps.values():
                    for bundle in dests.values():bundle.sort(key=lambda x:json.dumps(x,sort_keys=True))
            key=(tuple(ms),tuple(ds),json.dumps(ps,sort_keys=True))
            c=cache.get(key);hit=c is not None
            if hit:cache.move_to_end(key)
            else:
                vals,sups,order=brute(top,ms,prediction(top,ds,paths),paths is not None,sett['trials'],sett['epsilon'],sett['seed'])
                c=RepairCertificate(vals,sups,order)
                if sett['cache_slots']:
                    cache[key]=c
                    if len(cache)>sett['cache_slots']:cache.popitem(last=False)
            snaps[e['id']]=copy.deepcopy(c)
            out.append(c.publish(top,sett['trials'],e['id'],hit))
        else:out.append(validate(top,snaps[e['id']],prediction(top,ds,paths),sett,e['id']))
    return out

def routes(top):
    names=list(top.names.values());out={}
    for a,b in top.demand_pairs:
        A,B=top.names[a],top.names[b]
        count=random.randrange(1,5)
        cuts=sorted(random.sample(range(1,1000),count-1))
        weights=[y-x for x,y in zip([0]+cuts,cuts+[1000])]
        bundle=[]
        for w in weights:
            interior=random.sample([x for x in names if x not in [A,B]],random.randrange(len(names)-1))
            bundle.append({'path':[A]+interior+[B],'weight':w})
        out.setdefault(A,{})[B]=bundle
    return out

random.seed(87234)
for iteration in range(80):
