                cs={k:random.choice([None,{'perturbed':random.randrange(top.counter_capacity[i]+1),'confidence':['ignore']}]) for i,k in enumerate(top.counter_keys) if random.random()<.5}
                E.append({'op':'patch','demands':ds,'counters':cs})
            else:
                E.append({'op':'patch','demands':[[*top.demand_pairs[0],10]],'counters':{'bad':{'perturbed':0}},'valid':False})
        elif t%6 in [2,3]:
